// Fixed pause rules, no AI: how long promos and review requests wait after each kind of problem.
// Each kind writes its own end date, so a short pause never cuts a longer one.
const event = $('Webhook: Carrier / Trustpilot / Zendesk Event').item.json.body || {};
const source = String(event.source || '').toLowerCase();

let type = 'ticket';
let days = 7;          // Zendesk ticket: 7 days after the latest ticket update (solved included)
if (source === 'trustpilot') {
  type = 'review';
  days = 30;           // 1-2 star review: 30 days
} else if (source === 'aftership' || source === 'sendcloud') {
  type = 'delivery';
  days = 14;           // carrier exception: 14 days, pushed forward by every new exception
}

const until = new Date(Date.now() + days * 24 * 60 * 60 * 1000);
return {
  json: {
    hold_type: type,
    hold_days: days,
    hold_property: 'cx_hold_until_' + type,
    hold_until: until.toISOString().slice(0, 19).replace('T', ' '), // UTC, a date format Klaviyo reads
  },
};

const raw = String(
  $json.choices?.[0]?.message?.content ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  '{}'
).replace(/```json|```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (err) {
  parsed = {};
}

return {
  json: {
    theme: parsed.theme || 'cx_issue_open',
    priority_tier: parsed.priority_tier || 'P2',
    owner_team: parsed.owner_team || 'customer_service',
    internal_reply_draft: parsed.internal_reply_draft || 'AI draft unavailable — review order & customer context manually.'
  }
};

